module tb;
    // Declare inputs as regs, outputs as wires
    reg  [1023:0] in;
    reg  [7:0]    sel;
    wire [3:0]    out;

    // Instantiate TopModule
    TopModule dut (
        .in  (in),
        .sel (sel),
        .out (out)
    );

    integer errors = 0;
    integer i;
    reg [3:0] expected_out;

    initial begin
        // Initialize inputs
        in = 1024'h0;
        sel = 8'h0;
        #5;

        // Drive a known pattern across the 1024-bit input vector.
        // Each 4-bit chunk gets a unique value based on its index (modulo 16).
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0];
        end
        #5;

        // Test a representative set of select values (0, 1, 2, 10, 100, 255)
        // plus a randomized loop of tests.

        // Targeted checks
        sel = 8'd0;   #5;
        expected_out = in[sel*4 +: 4];
        if (out !== expected_out) errors = errors + 1;

        sel = 8'd1;   #5;
        expected_out = in[sel*4 +: 4];
        if (out !== expected_out) errors = errors + 1;

        sel = 8'd15;  #5;
        expected_out = in[sel*4 +: 4];
        if (out !== expected_out) errors = errors + 1;

        sel = 8'd127; #5;
        expected_out = in[sel*4 +: 4];
        if (out !== expected_out) errors = errors + 1;

        sel = 8'd255; #5;
        expected_out = in[sel*4 +: 4];
        if (out !== expected_out) errors = errors + 1;

        // Bounded loop checking multiple arbitrary select lines
        for (i = 0; i < 15; i = i + 1) begin
            sel = $unsigned($random) % 256;
            #5;
            expected_out = in[sel*4 +: 4];
            if (out !== expected_out) begin
                errors = errors + 1;
            end
        end

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
